/// The info option methods of a fluent URL builder: one per option name
/// and alias, each appending that option written with the name as called.
///
/// `T` is the concrete builder, which every method returns.
mixin InfoMethods<T> {
  /// Appends one option occurrence by name or alias.
  T option(String name, List<Object?> args);

  /// Report whether the source has alpha.
  ///
  /// URL names: `alpha`, `a`; arguments `alpha:check_transparency`; default false:false. Milestone M1; scope request.
  ///
  /// - `alpha`: report the alpha channel. Null writes an empty argument.
  /// - `checkTransparency`: check for transparent pixels (not implemented). Null writes an empty argument.
  T alpha(bool? alpha, [bool? checkTransparency]) => option('alpha', trimArgs([alpha, checkTransparency], 1));

  /// Report whether the source has alpha.
  ///
  /// URL names: `alpha`, `a`; arguments `alpha:check_transparency`; default false:false. Milestone M1; scope request.
  ///
  /// - `alpha`: report the alpha channel. Null writes an empty argument.
  /// - `checkTransparency`: check for transparent pixels (not implemented). Null writes an empty argument.
  T a(bool? alpha, [bool? checkTransparency]) => option('a', trimArgs([alpha, checkTransparency], 1));

  /// Report the average colour.
  ///
  /// URL names: `average`, `avg`; arguments `enabled:ignore_transparent`; default false:true. Milestone M2; scope request.
  ///
  /// - `enabled`: report the average colour. Null writes an empty argument.
  /// - `ignoreTransparent`: ignore transparent pixels (default true). Null writes an empty argument.
  T average(bool? enabled, [bool? ignoreTransparent]) => option('average', trimArgs([enabled, ignoreTransparent], 1));

  /// Report the average colour.
  ///
  /// URL names: `average`, `avg`; arguments `enabled:ignore_transparent`; default false:true. Milestone M2; scope request.
  ///
  /// - `enabled`: report the average colour. Null writes an empty argument.
  /// - `ignoreTransparent`: ignore transparent pixels (default true). Null writes an empty argument.
  T avg(bool? enabled, [bool? ignoreTransparent]) => option('avg', trimArgs([enabled, ignoreTransparent], 1));

  /// Report the number of bands.
  ///
  /// URL names: `bands`, `b`; arguments `bool`; default false. Milestone M1; scope request.
  ///
  /// - `bands`: Report the number of bands. Null writes an empty argument.
  T bands(bool? bands) => option('bands', [bands]);

  /// Report the number of bands.
  ///
  /// URL names: `bands`, `b`; arguments `bool`; default false. Milestone M1; scope request.
  ///
  /// - `bands`: Report the number of bands. Null writes an empty argument.
  T b(bool? bands) => option('b', [bands]);

  /// Report a BlurHash.
  ///
  /// URL names: `blurhash`, `bh`; arguments `x:y (1..9 each, 0:0 off)`; default 0:0. Milestone M2; scope request.
  ///
  /// - `xComponents`: 1..9; 0:0 = off. Range ≥ 0, ≤ 9.
  /// - `yComponents`: 1..9; 0:0 = off. Range ≥ 0, ≤ 9.
  T blurhash(int xComponents, int yComponents) => option('blurhash', [xComponents, yComponents]);

  /// Report a BlurHash.
  ///
  /// URL names: `blurhash`, `bh`; arguments `x:y (1..9 each, 0:0 off)`; default 0:0. Milestone M2; scope request.
  ///
  /// - `xComponents`: 1..9; 0:0 = off. Range ≥ 0, ≤ 9.
  /// - `yComponents`: 1..9; 0:0 = off. Range ≥ 0, ≤ 9.
  T bh(int xComponents, int yComponents) => option('bh', [xComponents, yComponents]);

  /// Skip the result cache (XI_CACHE_ALLOW_BYPASS).
  ///
  /// URL names: `bypass_cache`, `bc`; arguments `bool`; default false. Milestone M2 (WP-52); scope request. imgproxy Pro option (free here).
