/// The video option methods of a fluent URL builder: one per option name
/// and alias, each appending that option written with the name as called.
///
/// `T` is the concrete builder, which every method returns.
mixin VideoMethods<T> {
  /// Appends one option occurrence by name or alias.
  T option(String name, List<Object?> args);

  /// Audio bit rate (8k..512k; ignored by flac and wav).
  ///
  /// URL names: `audio_bitrate`, `ab`; arguments `bit/s (k)`; default codec default. Milestone M5 (WP-123); scope request.
  ///
  /// - `bitrate`: bits per second, k suffix.
  T audioBitrate(String bitrate) => option('audio_bitrate', [bitrate]);

  /// Audio bit rate (8k..512k; ignored by flac and wav).
  ///
  /// URL names: `audio_bitrate`, `ab`; arguments `bit/s (k)`; default codec default. Milestone M5 (WP-123); scope request.
  ///
  /// - `bitrate`: bits per second, k suffix.
  T ab(String bitrate) => option('ab', [bitrate]);

  /// Downmix to mono or stereo.
  ///
  /// URL names: `audio_channels`, `ach`; arguments `1 or 2`; default source. Milestone M5 (WP-123); scope request.
  ///
  /// - `channels`: 1 mono, 2 stereo; 0 = source (at most 2). Range ≥ 0, ≤ 2.
  T audioChannels(int channels) => option('audio_channels', [channels]);

  /// Downmix to mono or stereo.
  ///
